event: response.output_text.done
data: {"type":"response.output_text.done","content_index":0,"item_id":"msg_0d1bff1518122f65006aa7003bd9fc87d2a7be3e2fe62c3630","logprobs":[],"output_index":0,"sequence_number":335,"text":"{\"name\":\"Classic Margherita Pizza\",\"ingredients\":[\"2 cups all-purpose flour\",\"1 teaspoon active dry yeast\",\"3/4 cup warm water\",\"1 teaspoon salt\",\"1 teaspoon sugar\",\"1 tablespoon olive oil\",\"1/2 cup tomato sauce\",\"1 1/2 cups fresh mozzarella cheese, sliced\",\"Fresh basil leaves\",\"Salt to taste\",\"Olive oil for drizzling\"],\"steps\":[\"In a bowl, mix warm water, yeast, and sugar. Let it sit for about 5 minutes until frothy.\",\"In another bowl, combine flour and salt. Create a well in the center and pour in the yeast mixture and olive oil.\",\"Mix until a dough forms, then knead on a floured surface for about 10 minutes until smooth.\",\"Place the dough in a greased bowl, cover with a damp cloth, and let it rise in a warm place for about 1 hour, or until doubled in size.\",\"Preheat the oven to its highest setting (usually around 475°F or 245°C). If using a pizza stone, place it in the oven to preheat.\",\"Punch down the risen dough and roll it out on a floured surface into a 12-inch circle.\",\"Transfer the dough to a pizza peel or baking sheet. Spread the tomato sauce evenly over the base.\",\"Lay the mozzarella slices over the sauce and sprinkle a little salt on top.\",\"Bake in the preheated oven (preferably on the pizza stone) for about 10-12 minutes or until the crust is golden and the cheese is bubbly.\",\"Remove from the oven and add fresh basil leaves and a drizzle of olive oil before slicing and serving.\"]}"}

